COMPONENT [procedural-polygon-from-seed]: Generate an irregular convex-ish polygon (asteroid/rock/island) by jittering radius per angle from a seed, so shapes are NOT perfect circles. Reuse the same vertex list each frame.
```js
// Build once per entity (store verts), draw every frame.
function makePolygon(radius, points = 11, jitter = 0.4) {
  const verts = [];
  for (let i = 0; i < points; i++) {
    const a = (i / points) * Math.PI * 2;
    const r = radius * (1 - jitter/2 + Math.random() * jitter);
    verts.push({ x: Math.cos(a) * r, y: Math.sin(a) * r });
  }
  return verts; // irregular outline, never a circle
}
function drawPolygon(ctx, e) {
  ctx.save(); ctx.translate(e.x, e.y); ctx.rotate(e.rot || 0);
  ctx.beginPath();
  e.verts.forEach((v, i) => i ? ctx.lineTo(v.x, v.y) : ctx.moveTo(v.x, v.y));
  ctx.closePath(); ctx.stroke();
  ctx.restore();
}
```

COMPONENT [screen-wrap-toroidal]: Toroidal screen wrap: entities leaving one edge reappear on the opposite edge (asteroids-style). Wrap positions after integration, not before.
```js
// Call after moving each entity. W,H are the play-field size.
function wrap(e, W, H) {
  if (e.x < 0) e.x += W; else if (e.x >= W) e.x -= W;
  if (e.y < 0) e.y += H; else if (e.y >= H) e.y -= H;
}
// For objects with radius, wrap by their full extent so they slide off
// smoothly instead of popping:
function wrapR(e, W, H, r) {
  if (e.x < -r) e.x = W + r; else if (e.x > W + r) e.x = -r;
  if (e.y < -r) e.y = H + r; else if (e.y > H + r) e.y = -r;
}
```

COMPONENT [countdown-timer]: Countdown timer that ticks down only while not paused and fires an onExpire callback exactly once (level time limit, game over).
```js
function makeTimer(seconds, onExpire) { return { left: seconds, total: seconds, expired: false, onExpire }; }
function updateTimer(t, dt, paused = false) {
  if (t.expired || paused) return;
  t.left -= dt;
  if (t.left <= 0) { t.left = 0; t.expired = true; if (t.onExpire) t.onExpire(); }
}
function resetTimer(t) { t.left = t.total; t.expired = false; }
// Expose: state.timeLeft = Math.ceil(t.left);  // HUD + probe-readable
```
